const e = $json;

// Works with both Gmail formats: simple=false (from/subject/text/html) and simple=true (From/Subject/snippet)
let body = e.text || (e.html || '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ');
if (!body) body = e.snippet || '';

body = body
  .replace(/[͏​-‍﻿]/g, '') // invisible characters used in newsletters
  .replace(/\s+/g, ' ')
  .split(/On .+ wrote:|-----Original Message-----/)[0] // drop quoted replies
  .trim()
  .slice(0, 3000);

return {
  id: e.id,
  threadId: e.threadId,
  from: e.from?.value?.[0]?.address || e.from?.text || e.From || '',
  subject: e.subject || e.Subject || '(no subject)',
  date: e.date || (e.internalDate ? new Date(Number(e.internalDate)).toISOString() : ''),
  link: `https://mail.google.com/mail/u/0/#all/${e.threadId || e.id}`,
  body
};

const TZ = 'Asia/Gaza';
const R = '‏'; // right-to-left mark, so lines that mix Arabic and English still align right
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const DAYS = ['الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت', 'الأحد'];

const fmtDate = (iso, withTime) => {
  if (!iso) return '';
  const d = DateTime.fromISO(iso, { zone: TZ });
  if (!d.isValid) return esc(iso);
  const today = DateTime.now().setZone(TZ).startOf('day');
  const diff = Math.round(d.startOf('day').diff(today, 'days').days);
  const rel = diff === 0 ? 'اليوم' : diff === 1 ? 'بكرة' : `${DAYS[d.weekday - 1]} ${d.toFormat('d/M')}`;
  return withTime ? `${rel} · ${d.toFormat('HH:mm')}` : rel;
};

// "📝 Course - Title" → { icon, course, title }
const split = full => {
  const s = String(full || '').trim();
  const m = s.match(/^(\p{Extended_Pictographic}️?)\s*(.*)$/u);
  const icon = m ? m[1] : '•';
  let rest = (m ? m[2] : s).replace(/^Deadline:\s*/i, '');
  const i = rest.indexOf(' - ');
  return i > 0
    ? { icon, course: rest.slice(0, i).trim(), title: rest.slice(i + 3).trim() }
    : { icon, course: '', title: rest };
};

const parse = raw => {
  try {
    const c = String(raw).replace(/```json|```/g, '').trim();
    return JSON.parse(c.slice(c.indexOf('{'), c.lastIndexOf('}') + 1));
  } catch (e) { return null; }
};

const countText = n => n === 1 ? 'إيميل واحد جديد' : n === 2 ? 'إيميلين جداد' : n <= 10 ? `${n} إيميلات جديدة` : `${n} إيميل جديد`;

const emails = $('Clean Email').all();
const tasks = [], events = [], dups = [], warns = [], ignored = [], unparsed = [];

$input.all().forEach((item, idx) => {
  const link = emails[idx]?.json?.link;
  const open = link ? ` <a href="${link}">↗️</a>` : '';
  const r = parse(item.json.output);
  if (!r) { unparsed.push(`${R}${esc(item.json.output)}`); return; }

  for (const t of r.added_tasks || []) {
    const p = split(t.title);
    const meta = [p.course && `📘 ${esc(p.course)}`, t.due && `⏳ ${fmtDate(t.due)}`].filter(Boolean).join('  ·  ');
    tasks.push(`${R}☐ ${p.icon} <b>${esc(p.title)}</b>${open}${meta ? `\n${R}      ${meta}` : ''}`);
  }
  for (const ev of r.added_events || []) {
    const p = split(ev.title);
    const label = /deadline/i.test(ev.title) ? 'تسليم: ' : '';
    const meta = [`🕒 ${fmtDate(ev.start, true)}`, ev.location && `📍 ${esc(ev.location)}`, p.course && `📘 ${esc(p.course)}`].filter(Boolean).join('  ·  ');
    events.push(`${R}${p.icon} <b>${label}${esc(p.title)}</b>${open}\n${R}      ${meta}`);
  }
  for (const d of r.duplicates || []) {
    const p = split(d);
    dups.push(`${R}${p.icon} ${esc(p.title)}${p.course ? ` <i>(${esc(p.course)})</i>` : ''}`);
  }
  for (const w of r.warnings || []) warns.push(`${R}❗ ${esc(w)}${open}`);

  const did = (r.added_tasks || []).length + (r.added_events || []).length + (r.duplicates || []).length + (r.warnings || []).length;
  if (!did) ignored.push(`${R}▫️ ${esc(r.subject)}`);
});

const now = DateTime.now().setZone(TZ);
const header = `${R}🎓 <b>تقرير الجامعة</b>\n${R}🗓 ${DAYS[now.weekday - 1]} ${now.toFormat('d/M')} · ${now.toFormat('HH:mm')}  |  📬 ${countText($input.all().length)}`;

const parts = [header];
if (tasks.length)  parts.push(`${R}✅ <b>مهام جديدة (${tasks.length})</b>\n\n${tasks.join('\n\n')}`);
if (events.length) parts.push(`${R}📅 <b>مواعيد انضافت للكلندر (${events.length})</b>\n\n${events.join('\n\n')}`);
if (warns.length)  parts.push(`${R}⚠️ <b>بدها انتباهك</b>\n\n${warns.join('\n')}`);
if (dups.length)   parts.push(`${R}🔁 <b>موجودة من قبل (ما كررتها)</b>\n${dups.join('\n')}`);
if (ignored.length) parts.push(`${R}📭 <b>إيميلات مش دراسية (${ignored.length})</b>\n${ignored.join('\n')}`);
if (unparsed.length) parts.push(`${R}❓ <b>ما قدرت أنسقهم</b>\n${unparsed.join('\n\n')}`);
if (!tasks.length && !events.length && !warns.length) parts.push(`${R}✨ ما في شي جديد بده شغل — ارتاحي 😌`);

return [{ json: { text: parts.join('\n\n────────────\n\n') } }];
